parts.text:
{
  "extractions": [
    {
      "unit": "F001",
      "unit_attributes": {
        "modality_explanation": "The text states an employee 'must provide notice' under these circumstances, creating a mandatory requirement.",
        "statement": "When the approximate timing of the need for leave is not foreseeable, an employee must provide notice to the employer as soon as practicable under the facts and circumstances of the particular case.",
        "kind": "requirement",
        "modality": "must",
        "modality_quote": "must"
      }
    },
    {
      "unit": "F001",
      "unit_attributes": {
        "modality_explanation": "The source uses 'should' qualified by 'generally', expressing an advisory or standard expectation rather than an absolute duty.",
        "statement": "It generally should be practicable for an employee to provide notice of leave that is unforeseeable within the time prescribed by the employer's usual and customary notice requirements applicable to such leave (see § 825.303(c)).",
        "kind": "recommendation",
        "modality": "should",
        "modality_quote": "should",
        "references": [
          "§ 825.303(c)"
        ]
      }
    },
    {
      "unit": "F001",
      "unit_attributes": {
        "modality_explanation": "The source uses 'may be given', conferring permission for a spokesperson to provide notice when the employee is unable to do so personally.",
        "statement": "Notice may be given by the employee's spokesperson (such as a spouse, adult family member, or other responsible party) if the employee is unable to do so personally.",
        "kind": "permission",
        "modality": "may",
        "modality_quote": "may"
      }
    },
    {
      "unit": "F001",
      "unit_attributes": {
        "modality_explanation": "The phrase 'would not be required' explicitly establishes an absence of duty under the stated emergency room facts.",
        "statement": "If an employee's child has a severe asthma attack and the employee takes the child to the emergency room, the employee would not be required to leave his or her child in order to report the absence while the child is receiving emergency treatment.",
        "kind": "exemption",
        "modality": "not_required",
        "modality_quote": "would not be required"
      }
    },
    {
      "unit": "F001",
      "unit_attributes": {
        "modality_explanation": "The phrase 'would be expected to' establishes a normative expectation/standard under the specified circumstances.",
        "statement": "If a child's asthma attack required only the use of an inhaler at home followed by a period of rest, the employee would be expected to call the employer promptly after ensuring the child has used the inhaler.",
        "kind": "recommendation",
        "modality": "should",
        "modality_quote": "would be expected to"
      }
    },
    {
      "unit": "F002",
      "unit_attributes": {
        "modality_explanation": "'Shall provide' imposes a mandatory duty on the employee.",
        "statement": "An employee shall provide sufficient information for an employer to reasonably determine whether the FMLA may apply to the leave request.",
        "kind": "requirement",
        "modality": "must",
        "modality_quote": "shall"
      }
    },
    {
      "unit": "F002",
      "unit_attributes": {
        "modality_explanation": "'May include' introduces descriptive possibilities of what information might encompass depending on the situation.",
        "statement": "Depending on the situation, information provided by an employee may include that a condition renders the employee unable to perform the functions of the job; that the employee is pregnant or has been hospitalized overnight; whether the employee or the employee's family member is under the continuing care of a health care provider; if the leave is due to a qualifying exigency, that a military member is on covered active duty or call to covered active duty status (or has been notified of an impending call or order to covered active duty), that the requested leave is for one of the reasons listed in § 825.126(b), and the anticipated duration of the absence; or if the leave is for a family member, that the condition renders the family member unable to perform daily activities or that the family member is a covered servicemember with a serious injury or illness; and the anticipated duration of the absence, if known.",
        "kind": "statement",
        "modality": "possible",
        "modality_quote": "may include",
        "references": [
          "§ 825.126(b)"
        ]
      }
    },
    {
      "unit": "F002",
      "unit_attributes": {
        "modality_explanation": "'Need not' explicitly relieves the employee of the obligation to assert FMLA rights or mention the FMLA.",
        "statement": "When an employee seeks leave for the first time for a FMLA-qualifying reason, the employee need not expressly assert rights under the FMLA or even mention the FMLA.",
        "kind": "exemption",
        "modality": "not_required",
        "modality_quote": "need not"
      }
    },
    {
      "unit": "F002",
      "unit_attributes": {
        "modality_explanation": "'Must specifically reference' imposes a mandatory obligation on the employee.",
        "statement": "When an employee seeks leave due to a qualifying reason for which the employer has previously provided the employee FMLA-protected leave, the employee must specifically reference either the qualifying reason for leave or the need for FMLA leave.",
        "kind": "requirement",
        "modality": "must",
        "modality_quote": "must"
      }
    },
    {
      "unit": "F002",
      "unit_attributes": {
        "modality_explanation": "'Will not be considered' is a declarative statement of legal insufficiency.",
        "statement": "Calling in “sick” without providing more information will not be considered sufficient notice to trigger an employer's obligations under the Act.",
        "kind": "statement",
        "modality": "not_stated"
      }
    },
    {
      "unit": "F002",
      "unit_attributes": {
        "modality_explanation": "'Will be expected to' establishes a normative standard/expectation for the employer.",
        "statement": "The employer will be expected to obtain any additional required information through informal means.",
        "kind": "recommendation",
        "modality": "should",
        "modality_quote": "will be expected to"
      }
    },
    {
      "unit": "F002",
      "unit_attributes": {
        "modality_explanation": "'Has an obligation to' establishes a mandatory requirement for the employee.",
        "statement": "An employee has an obligation to respond to an employer's questions designed to determine whether an absence is potentially FMLA-qualifying.",
        "kind": "requirement",
        "modality": "must",
        "modality_quote": "has an obligation to"
      }
    },
    {
      "unit": "F002",
      "unit_attributes": {
        "modality_explanation": "'May result' describes a potential consequence rather than granting permission.",
        "statement": "Failure to respond to reasonable employer inquiries regarding the leave request may result in denial of FMLA protection if the employer is unable to determine whether the leave is FMLA-qualifying.",
        "kind": "statement",
        "modality": "possible",
        "modality_quote": "may"
      }
    },
    {
      "unit": "F003:F004",
      "unit_attributes": {
        "modality_explanation": "'Must comply' establishes an obligation on the employee, qualified by the absence of unusual circumstances.",
        "statement": "When the need for leave is not foreseeable, an employee must comply with the employer's usual and customary notice and procedural requirements for requesting leave, absent unusual circumstances.",
        "kind": "requirement",
        "modality": "must",
        "modality_quote": "must"
      }
    },
    {
      "unit": "F004",
      "unit_attributes": {
        "modality_explanation": "'May require' conveys an employer's permission or authority to implement specific call-in procedures.",
        "statement": "An employer may require employees to call a designated number or a specific individual to request leave.",
        "kind": "permission",
        "modality": "may",
        "modality_quote": "may"
      }
    },
    {
      "unit": "F004",
      "unit_attributes": {
        "modality_explanation": "'Would not be required' explicitly denotes an absence of duty under the specified conditions until stabilization and access.",
        "statement": "If an employee requires emergency medical treatment, he or she would not be required to follow the call-in procedure until his or her condition is stabilized and he or she has access to, and is able to use, a phone.",
        "kind": "exemption",
        "modality": "not_required",
        "modality_quote": "would not be required"
      }
    },
    {
      "unit": "F004",
      "unit_attributes": {
        "modality_explanation": "'May not be required' indicates that written advance notice is not unconditionally required under employer internal procedures during qualifying emergencies.",
        "statement": "In the case of an emergency requiring leave because of a FMLA-qualifying reason, written advance notice pursuant to an employer's internal rules and procedures may not be required when FMLA leave is involved.",
        "kind": "exemption",
        "modality": "not_required",
        "modality_quote": "may not be required"
      }
    },
    {
      "unit": "F004",
      "unit_attributes": {
        "modality_explanation": "'May be delayed or denied' indicates a possible outcome under the stated conditions.",
        "statement": "If an employee does not comply with the employer's usual notice and procedural requirements, and no unusual circumstances justify the failure to comply, FMLA-protected leave may be delayed or denied.",
        "kind": "statement",
        "modality": "possible",
        "modality_quote": "may be"
      }
    }
  ]
}
